#[cfg(test)]
mod source_reload_regression {
 use super::*;
 #[test]
 fn replacement_must_not_reuse_previous_preview() {
  let dir = tempfile::tempdir().unwrap();
  let path = dir.path().join("source.raw");
  std::fs::write(&path, b"original").unwrap();
  let mut editor = Editor::new(MemoryBudget::new(1024*1024), dir.path().join("journal"));
  editor.activate(path.clone(), 0).unwrap();
  editor.apply_exposure(1.5).unwrap();
  editor.shutdown();
  std::fs::write(&path, b"replaced").unwrap();
  editor.activate(path, 0).unwrap();
  assert_eq!(editor.current(), EditState::default(), "old exposure leaked into replacement preview");
 }
}
